import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C3unmAF4.js";const d=JSON.parse('{"title":"从“会种地”到“慧种地” 智慧农业点亮特色产业共富路","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"从“会种地”到“慧种地” 智慧农业点亮特色产业共富路","date":"2026-05-26T00:00:00.000Z","source":"中国农业信息网","category":"news","link":"https://www.agri.cn/xxh/zhny/202605/t20260529_8840352.htm","summary":"初夏时节，走进“中国蔬菜之乡”山东省寿光市的纪都现代农业共富园区，智能温室里各类传感器像一双双敏锐的眼睛，实时捕捉小番茄、草莓、甜瓜等果蔬种植区的温度、湿度、光照强度变化，园区智慧控制系统根据参数自动进行灌溉、通风、补光。\\n“过去种菜要靠经验去判断水和肥，现在依靠温湿度智能控制系统、水肥一体化系统、补光自动化系统等，不仅节水节肥30%以上，劳动生产效率还提高一倍。...\\n","contentHash":"4870519b887bb37c1c4bc1e13b5f5691","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-05-26-从-会种地-到-慧种地-智慧农业点亮特色产业共富路.md","filePath":"news/2026-05-26-从-会种地-到-慧种地-智慧农业点亮特色产业共富路.md"}'),p={name:"news/2026-05-26-从-会种地-到-慧种地-智慧农业点亮特色产业共富路.md"};function n(s,e,o,l,c,i){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="从-会种地-到-慧种地-智慧农业点亮特色产业共富路" tabindex="-1">从“会种地”到“慧种地” 智慧农业点亮特色产业共富路 <a class="header-anchor" href="#从-会种地-到-慧种地-智慧农业点亮特色产业共富路" aria-label="Permalink to &quot;从“会种地”到“慧种地” 智慧农业点亮特色产业共富路&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.agri.cn/xxh/zhny/202605/t20260529_8840352.htm" target="_blank" rel="noreferrer">中国农业信息网</a><br> 日期: 2026-05-26 摘要: 初夏时节，走进“中国蔬菜之乡”山东省寿光市的纪都现代农业共富园区，智能温室里各类传感器像一双双敏锐的眼睛，实时捕捉小番茄、草莓、甜瓜等果蔬种植区的温度、湿度、光照强度变化，园区智慧控制系统根据参数自动进行灌溉、通风、补光。 “过去种菜要靠经验去判断水和肥，现在依靠温湿度智能控制系统、水肥一体化系统、补光自动化系统等，不仅节水节肥30%以上，劳动生产效率还提高一倍。...</p></blockquote><p>初夏时节，走进“中国蔬菜之乡”山东省寿光市的纪都现代农业共富园区，智能温室里各类传感器像一双双敏锐的眼睛，实时捕捉小番茄、草莓、甜瓜等果蔬种植区的温度、湿度、光照强度变化，园区智慧控制系统根据参数自动进行灌溉、通风、补光。</p><p>“过去种菜要靠经验去判断水和肥，现在依靠温湿度智能控制系统、水肥一体化系统、补光自动化系统等，不仅节水节肥30%以上，劳动生产效率还提高一倍。”寿光市华耕农业科技有限公司董事长张东升说。</p><p>“十五五”规划纲要提出“加快建设农业强国”。作为农业大省，近年来，山东充分运用物联网、云计算等技术，大力推进智慧农业发展，让数智化技术成为助力乡村振兴、产业增效的新引擎。</p><p>寿光市纪台镇镇长高军说，2024年他们整合资金建成纪都现代农业共富园区，实行“镇村共富公司＋农业龙头企业＋农户”三方运营模式，新建大棚全面推广自动温控、智能雾化等智能设备，确保果蔬在适宜环境下生长。</p><p>从“会种地”到“慧种地”，既提高了作物产量和品质，又节约了能源和资源。“天冷开保温、天热开遮阳、干了开喷灌，手机一点就能远程操控，省心又高产。”纪台镇东埠村村民张立强说，他在园区种了4个大棚，一年能种三茬羊角蜜甜瓜，去年纯收入近50万元。</p><p>目前，这个共富园区已吸引数十户种植户在此租棚种菜，扣除租金后每年户均纯收入20多万元；带动周边1000多个老旧大棚完成改造升级，促进周边27个村去年集体收入共计增收100多万元。</p><p>寿光市蔬菜高科技示范园管理服务中心党组书记、主任燕黎明说，近年来，寿光持续推进农业数智化升级，新建大棚中，AI种植管理系统和巡检机器人等智能化装备普及率、物联网应用率、标准化生产推广率均超85%，科技进步对农业增长的贡献率突破70%。</p><p>从“靠天吃饭”到“智能控制”，数智化技术赋能现代农业发展在山东多地落地生根。</p><p>在烟台市蓬莱区村里集镇古城苗家村有机蟠桃示范基地，大棚环境智能调控系统自动识别温度、湿度参数变化，自动控制采光调温。今年，这个示范基地的有机蟠桃亩均产量在3000斤左右，相比传统露天种植增产超40%，亩均纯收入预计可达3万多元。</p><p>有机蟠桃示范基地负责人纪少利说，针对现代果蔬产业的用电需求，国网烟台市蓬莱区供电公司升级改造了周边3.2公里的电力线路，将电力线路架设到基地“家门口”，减少了他们的接电成本；“一棚一档”建立用电“健康档案”，并利用红外测温等手段定期“把脉问诊”，为基地发展保驾护航。近几年，基地带动周边4个村的30多户种植户年均增收300多万元。</p><p>科技赋能加快发展农业新质生产力，让传统农业迈入精准化、智能化新阶段，推动农业从“汗水农业”向智慧农业转型，为乡村振兴注入持久动力。（新华社记者 王志）</p><p><a href="https://www.agri.cn/xxh/zhny/202605/t20260529_8840352.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',14)])])}const f=t(p,[["render",n]]);export{d as __pageData,f as default};
